INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_ISLAMIC_TRADITION','secondary scholarship','Classical Sunni Islamic tradition (the schools of law; the devotional enumeration of the Ninety-Nine Names)','Islamic')
INSERT INTO _e VALUES
 ('ENT_ISR_ABIJAH','Abijah (Abijam)','Israelite/Second Temple','King','King of Judah','Davidic continuity; war with Jeroboam I','A','Son of Rehoboam who warred against Jeroboam I and won at Mount Zemaraim, reigning three years.'),
 ('ENT_ISR_ATHALIAH','Athaliah','Israelite/Second Temple','Queen','Queen of Judah','usurpation; Baalist purge of the Davidic line','A','Daughter of Ahab/Jezebel who seized Judah''s throne after Ahaziah''s death and slaughtered the royal heirs, ruling six years until executed by Jehoiada.'),
 ('ENT_ISR_JEHORAM_JUDAH','Jehoram (king of Judah)','Israelite/Second Temple','King','King of Judah','Omride marriage alliance; apostasy','A','Son of Jehoshaphat who married Athaliah, killed his brothers, lost Edom in revolt, and died of an incurable disease.'),
 ('ENT_ISR_AHAZIAH_JUDAH','Ahaziah (king of Judah)','Israelite/Second Temple','King','King of Judah','Omride alliance; war against Aram','A','Son of Jehoram and Athaliah who reigned one year and was killed by Jehu during his revolt.'),
 ('ENT_ISR_JOASH_JUDAH','Joash (king of Judah)','Israelite/Second Temple','King','King of Judah','Temple repair; rescue of the Davidic line','A','Hidden as an infant from Athaliah and enthroned at seven by the priest Jehoiada; repaired the Temple but later apostatized and was assassinated.'),
 ('ENT_ISR_AMAZIAH','Amaziah','Israelite/Second Temple','King','King of Judah','reconquest of Edom; defeat by Israel','A','Son of Joash who defeated Edom but was beaten and captured by Jehoash of Israel and later killed in a conspiracy at Lachish.'),
 ('ENT_ISR_JOTHAM','Jotham','Israelite/Second Temple','King','King of Judah','building projects; co-regency','A','Son of Uzziah who served as regent during his father''s leprosy, built the Upper Gate of the Temple, and is judged generally righteous.'),
 ('ENT_ISR_AMON_JUDAH','Amon (king of Judah)','Israelite/Second Temple','King','King of Judah','idolatry; brief reign cut short by assassination','A','Son of Manasseh who continued his father''s idolatry and was assassinated by his servants after two years.'),
 ('ENT_ISR_JEHOAHAZ_JUDAH','Jehoahaz (king of Judah)','Israelite/Second Temple','King','King of Judah','three-month reign; deposed by Egypt','A','Son of Josiah (Shallum) who reigned three months before Pharaoh Necho deposed him and carried him to Egypt, where he died.'),
 ('ENT_ISR_JEHOIAKIM','Jehoiakim','Israelite/Second Temple','King','King of Judah','Egyptian then Babylonian vassalage; rebellion','A','Son of Josiah installed by Necho who became Nebuchadnezzar''s vassal, rebelled, burned Jeremiah''s scroll, and died as Babylon advanced.'),
 ('ENT_ISR_JEHOIACHIN','Jehoiachin (Jeconiah)','Israelite/Second Temple','King','King of Judah','the first deportation; exile in Babylon','A','Son of Jehoiakim who reigned three months before surrendering in the 597 BCE deportation, later released from prison by Evil-merodach.'),
 ('ENT_ISR_NADAB','Nadab','Israelite/Second Temple','King','King of Israel','short reign; end of Jeroboam''s house','A','Son of Jeroboam I who reigned two years before Baasha assassinated him at Gibbethon and wiped out his father''s dynasty.'),
 ('ENT_ISR_BAASHA','Baasha','Israelite/Second Temple','King','King of Israel','usurpation; war with Judah','A','Founder of his own house who seized the throne by killing Nadab, warred against Asa, and was condemned by the prophet Jehu son of Hanani.'),
 ('ENT_ISR_ELAH','Elah','Israelite/Second Temple','King','King of Israel','short reign ended by coup','A','Son of Baasha who reigned two years and was murdered while drunk by his chariot commander Zimri.'),
 ('ENT_ISR_ZIMRI','Zimri','Israelite/Second Temple','King','King of Israel','seven-day reign; suicide by fire','A','A chariot officer who killed Elah and reigned only seven days before Omri besieged him, whereupon he burned the palace over himself.'),
 ('ENT_ISR_TIBNI','Tibni','Israelite/Second Temple','King','King of Israel','contested kingship; civil-war rival of Omri','A','Son of Ginath supported by half of Israel against Omri in a succession struggle, but his faction was defeated and he died.'),
 ('ENT_ISR_AHAZIAH_ISRAEL','Ahaziah (king of Israel)','Israelite/Second Temple','King','King of Israel','Baal worship; fatal fall','A','Son of Ahab who reigned two years, served Baal, and after falling through a lattice consulted Baal-zebub and died as Elijah foretold.'),
 ('ENT_ISR_JEHORAM_ISRAEL','Jehoram (king of Israel)','Israelite/Second Temple','King','King of Israel','Moabite revolt; end of the house of Ahab','A','Son of Ahab (Joram) who fought Moab and Aram and was killed by Jehu during his coup, ending the Omride dynasty.'),
 ('ENT_ISR_JEHOAHAZ_ISRAEL','Jehoahaz (king of Israel)','Israelite/Second Temple','King','King of Israel','Aramean oppression; military decline','A','Son of Jehu whose reign saw Israel ground down by Hazael of Aram until only a remnant army remained.'),
 ('ENT_ISR_JEHOASH_ISRAEL','Jehoash (king of Israel)','Israelite/Second Temple','King','King of Israel','recovery against Aram; defeat of Judah','A','Son of Jehoahaz (Joash) who recovered cities from Aram per Elisha''s deathbed prophecy and defeated Amaziah of Judah.'),
 ('ENT_ISR_ZECHARIAH_ISRAEL','Zechariah (king of Israel)','Israelite/Second Temple','King','King of Israel','six-month reign; end of the house of Jehu','A','Son of Jeroboam II who reigned six months before Shallum assassinated him, ending Jehu''s dynasty in the fourth generation.'),
 ('ENT_ISR_SHALLUM_ISRAEL','Shallum (king of Israel)','Israelite/Second Temple','King','King of Israel','one-month reign by assassination','A','Son of Jabesh who killed Zechariah and reigned a single month before Menahem struck him down.'),
 ('ENT_ISR_MENAHEM','Menahem','Israelite/Second Temple','King','King of Israel','brutal consolidation; Assyrian tribute','A','Son of Gadi who seized power by killing Shallum, sacked Tiphsah, and paid tribute to Pul (Tiglath-pileser III) of Assyria.'),
 ('ENT_ISR_PEKAHIAH','Pekahiah','Israelite/Second Temple','King','King of Israel','short reign ended by his captain''s coup','A','Son of Menahem who reigned two years before his officer Pekah assassinated him in the citadel of Samaria.'),
 ('ENT_ISR_PEKAH','Pekah','Israelite/Second Temple','King','King of Israel','the Syro-Ephraimite war; Assyrian invasion','A','Son of Remaliah who killed Pekahiah, allied with Rezin of Aram against Judah, lost much land to Tiglath-pileser III, and was killed by Hoshea.'),
 ('ENT_ISR_HOSHEA','Hoshea','Israelite/Second Temple','King','King of Israel','last king of Israel; the fall of Samaria','A','Final northern king who killed Pekah, became an Assyrian vassal but conspired with Egypt, and was imprisoned as Samaria fell and Israel was deported in 722 BCE.'),
 ('ENT_NT_PROCHORUS','Prochorus','Christian/Biblical','Deacon','Apostolic figure','one of the Seven chosen to serve tables','A','One of the seven men of good repute appointed in Acts 6:5 to oversee the daily distribution to the Hellenist widows.'),
 ('ENT_NT_NICANOR','Nicanor','Christian/Biblical','Deacon','Apostolic figure','one of the Seven chosen to serve tables','A','One of the seven deacons named in Acts 6:5, set apart by the apostles with prayer and the laying on of hands.'),
 ('ENT_NT_TIMON','Timon','Christian/Biblical','Deacon','Apostolic figure','one of the Seven chosen to serve tables','A','One of the seven deacons listed in Acts 6:5 to relieve the apostles of the daily ministration.'),
 ('ENT_NT_PARMENAS','Parmenas','Christian/Biblical','Deacon','Apostolic figure','one of the Seven chosen to serve tables','A','One of the seven deacons named in Acts 6:5 among those chosen to administer the church''s daily distribution.'),
 ('ENT_NT_NICOLAUS','Nicolaus of Antioch','Christian/Biblical','Deacon','Apostolic figure','one of the Seven; a proselyte of Antioch','A','The last-named of the seven deacons in Acts 6:5, identified as a proselyte from Antioch.'),
 ('ENT_NT_CORNELIUS','Cornelius (the centurion)','Christian/Biblical','Roman official','Acts figure','the first Gentile convert; centurion of the Italian Cohort','A','A God-fearing centurion at Caesarea who, after a vision, was baptized by Peter and became the first Gentile convert (Acts 10).'),
 ('ENT_NT_ANANIAS_DAMASCUS','Ananias of Damascus','Christian/Biblical','Disciple','Apostolic figure','restored Saul''s sight and baptized him','A','A disciple at Damascus sent in a vision to lay hands on Saul of Tarsus, restoring his sight and baptizing him (Acts 9:10-19).'),
 ('ENT_NT_GAMALIEL','Gamaliel','Christian/Biblical','Apostolic figure','Pharisee teacher','the Pharisee teacher of the Law; teacher of Paul','A','A respected Pharisee who counseled restraint toward the apostles (Acts 5:34) and at whose feet Paul was educated (Acts 22:3).'),
 ('ENT_NT_AGABUS','Agabus','Christian/Biblical','Prophet','Apostolic figure','Christian prophecy; foretelling famine and Paul''s binding','A','A Christian prophet who foretold a great famine (Acts 11:28) and predicted Paul''s arrest in Jerusalem (Acts 21:10-11).'),
 ('ENT_NT_TABITHA','Tabitha (Dorcas)','Christian/Biblical','Disciple','Acts figure','charity and good works; raised from the dead','A','A disciple of Joppa known for charity and garment-making who was raised from the dead by Peter (Acts 9:36-42).'),
 ('ENT_NT_ETHIOPIAN_EUNUCH','The Ethiopian eunuch','Christian/Biblical','Acts figure','Court official','treasurer of Candace; early African convert baptized by Philip','A','The treasurer of Candace, queen of the Ethiopians, who was reading Isaiah when Philip explained the Scripture and baptized him (Acts 8:26-39).'),
 ('ENT_NT_PHOEBE','Phoebe (deaconess)','Christian/Biblical','Apostolic figure','Deaconess','deaconess of Cenchreae; patron and bearer of Paul''s letter to Rome','A','A deacon (diakonos) of the church at Cenchreae whom Paul commends as a benefactor and entrusts to the Roman church (Romans 16:1-2).'),
 ('ENT_NT_JUNIA','Junia','Christian/Biblical','Apostolic figure','Apostle','kinswoman and fellow prisoner of Paul; noted among the apostles','A','A kinswoman and fellow prisoner of Paul, greeted in Romans 16:7 as outstanding among the apostles.'),
 ('ENT_NT_ONESIMUS','Onesimus','Christian/Biblical','Disciple','Pauline associate','the runaway slave of Philemon turned Christian helper of Paul','A','The slave of Philemon who, converted by Paul in prison, was sent back as a beloved brother (Philemon 10-16).'),
 ('ENT_NT_PHILEMON','Philemon','Christian/Biblical','Disciple','Pauline associate','host of a house church at Colossae; master of Onesimus','A','A Christian of Colossae and host of a house church, addressed by Paul in the Epistle to Philemon on behalf of his slave Onesimus.'),
 ('ENT_NT_EPAPHRAS','Epaphras','Christian/Biblical','Disciple','Pauline associate','evangelist of Colossae; fellow prisoner of Paul','A','A fellow servant who brought the gospel to Colossae and is named as Paul''s fellow prisoner (Colossians 1:7; 4:12).'),
 ('ENT_NT_ONESIPHORUS','Onesiphorus','Christian/Biblical','Disciple','Pauline associate','refresher of Paul who sought him out in Rome','A','A supporter who often refreshed Paul and, unashamed of his chains, diligently sought him out in Rome (2 Timothy 1:16-18).'),
 ('ENT_ISL_FOUR_IMAMS','The Four Imams of the Sunni Schools of Law','Islamic','Collective','Jurist-founders collective','eponymous founders of the four Sunni madhhabs: Hanafi, Maliki, Shafi''i, Hanbali','A','Sunni Islam recognizes four orthodox schools of law, each named for a jurist of the 8th-9th centuries CE whose legal methodology it codified.'),
 ('ENT_ISL_ABU_HANIFA','Abu Hanifa','Islamic','Jurist-founder','Imam / school-founder','eponym of the Hanafi school; pioneer of ra''y and qiyas in fiqh','A','Abu Hanifa al-Nu''man ibn Thabit (c. 699-767 CE) of Kufa, eponymous founder of the Hanafi school, the most widely followed Sunni legal tradition.'),
 ('ENT_ISL_MALIK_IBN_ANAS','Malik ibn Anas','Islamic','Jurist-founder','Imam / school-founder','eponym of the Maliki school; compiler of the Muwatta; authority on Medinan practice','A','Malik ibn Anas (c. 711-795 CE) of Medina founded the Maliki school and authored the Muwatta, an early collection of hadith and law.'),
 ('ENT_ISL_AL_SHAFII','al-Shafi''i','Islamic','Jurist-founder','Imam / school-founder','eponym of the Shafi''i school; systematizer of usul al-fiqh','A','Muhammad ibn Idris al-Shafi''i (767-820 CE) founded the Shafi''i school and is regarded as the father of Islamic legal theory in his Risala.'),
 ('ENT_ISL_AHMAD_IBN_HANBAL','Ahmad ibn Hanbal','Islamic','Jurist-founder','Imam / school-founder','eponym of the Hanbali school; traditionist and compiler of the Musnad','A','Ahmad ibn Hanbal (780-855 CE) of Baghdad founded the Hanbali school, emphasized hadith over speculative reasoning, and compiled the vast Musnad.'),
 ('ENT_ISL_TALHA','Talha ibn Ubaydullah','Islamic','Companion','Companion / Ten Promised Paradise','early convert and warrior; shielded the Prophet at Uhud','A','One of the Ten Promised Paradise who famously shielded Muhammad at Uhud, sustaining wounds to his hand.'),
 ('ENT_ISL_AL_ZUBAYR','al-Zubayr ibn al-Awwam','Islamic','Companion','Companion / Ten Promised Paradise','early convert, cousin of the Prophet, cavalry commander','A','A paternal cousin of the Prophet and husband of Asma bint Abi Bakr, among the Ten Promised Paradise.'),
 ('ENT_ISL_ABD_AL_RAHMAN_IBN_AWF','Abd al-Rahman ibn Awf','Islamic','Companion','Companion / Ten Promised Paradise','wealthy early convert and merchant; member of the shura','A','A prosperous early Muslim merchant, one of the Ten Promised Paradise, and a member of Umar''s electoral council (shura).'),
 ('ENT_ISL_SAD_IBN_ABI_WAQQAS','Sa''d ibn Abi Waqqas','Islamic','Companion','Companion / Ten Promised Paradise','commander; victory over the Sasanians at al-Qadisiyya','A','One of the Ten Promised Paradise who commanded the army that defeated the Sasanian Persians at al-Qadisiyya.'),
 ('ENT_ISL_SAID_IBN_ZAYD','Sa''id ibn Zayd','Islamic','Companion','Companion / Ten Promised Paradise','very early convert; brother-in-law of Umar','A','One of the Ten Promised Paradise, an early convert whose conversion (with his wife Fatima) preceded Umar''s own.'),
 ('ENT_ISL_ABU_UBAYDA','Abu Ubayda ibn al-Jarrah','Islamic','Companion','Companion / Ten Promised Paradise','military commander; conquest of Syria; ''Trustee of this Nation''','A','One of the Ten Promised Paradise who commanded the conquest of Syria and was titled Amin al-Umma (Trustee of the Community).'),
 ('ENT_ISL_SAWDA','Sawda bint Zam''a','Islamic','Mother of the Believers','Wife of the Prophet','first wife after Khadijah''s death; early convert and Abyssinian emigrant','A','The first woman Muhammad married after Khadijah''s death, who had earlier emigrated to Abyssinia with her first husband.'),
 ('ENT_ISL_HAFSA','Hafsa bint Umar','Islamic','Mother of the Believers','Wife of the Prophet','daughter of Umar; keeper of the first written Qur''an','A','Daughter of the second caliph Umar, who kept the original compiled manuscript (suhuf) of the Qur''an after Abu Bakr.'),
 ('ENT_ISL_ZAYNAB_BINT_JAHSH','Zaynab bint Jahsh','Islamic','Mother of the Believers','Wife of the Prophet','cousin of the Prophet; her marriage referenced in Qur''an 33','A','The Prophet''s cousin and formerly wife of his adopted son Zayd, whose marriage is addressed in Surah al-Ahzab.'),
 ('ENT_ISL_UMM_SALAMA','Umm Salama','Islamic','Mother of the Believers','Wife of the Prophet','noted hadith narrator and counselor at Hudaybiyya','A','Hind bint Abi Umayya, a prolific narrator of hadith credited with the advice that resolved the crisis at Hudaybiyya.'),
 ('ENT_ISL_JUWAYRIYA','Juwayriya bint al-Harith','Islamic','Mother of the Believers','Wife of the Prophet','daughter of a Banu Mustaliq chief; her marriage freed her tribe''s captives','A','Daughter of the Banu Mustaliq chief; her marriage to the Prophet prompted Muslims to free their captives from her tribe.'),
 ('ENT_ISL_SAFIYYA','Safiyya bint Huyayy','Islamic','Mother of the Believers','Wife of the Prophet','of Jewish descent (Banu Nadir); married after Khaybar','A','A noblewoman of the Jewish Banu Nadir and daughter of its chief, who became the Prophet''s wife after the Battle of Khaybar.'),
 ('ENT_ISL_UMM_HABIBA','Umm Habiba','Islamic','Mother of the Believers','Wife of the Prophet','emigrant to Abyssinia; daughter of Abu Sufyan','A','Ramla bint Abi Sufyan, daughter of the Quraysh chief Abu Sufyan, an emigrant to Abyssinia married to the Prophet by proxy of the Negus.'),
 ('ENT_ISL_MAYMUNA','Maymuna bint al-Harith','Islamic','Mother of the Believers','Wife of the Prophet','last woman the Prophet married; aunt of Ibn Abbas and Khalid','A','The last woman Muhammad married, wed during the fulfilled compensatory pilgrimage (umrat al-qada) of 7 AH.'),
 ('ENT_ISL_ZAYNAB_BINT_KHUZAYMA','Zaynab bint Khuzayma','Islamic','Mother of the Believers','Wife of the Prophet','''Mother of the Poor'' (Umm al-Masakin); died soon after the marriage','A','Called Umm al-Masakin (''Mother of the Poor'') for her generosity, she died only a few months after marrying the Prophet.'),
 ('ENT_ISL_ASMA_AL_HUSNA','The Ninety-Nine Names of God (al-Asma al-Husna)','Islamic','Divine names','Divine names / devotional set','the ninety-nine Beautiful Names and attributes by which God is invoked in Islam','A','Al-Asma al-Husna are the ninety-nine Beautiful Names of God (al-Rahman, al-Rahim, al-Malik, ...) enumerated in tradition and recited in devotion; names of the one God, not separate beings.');
