 ('ENT_ISL_FOUR_IMAMS','SRC_ISLAMIC_TRADITION','Sunni Islam recognizes four orthodox schools of law, each named for a jurist of the 8th-9th centuries CE whose legal methodology it codified.','scholarly attestation'),
 ('ENT_ISL_ABU_HANIFA','SRC_ISLAMIC_TRADITION','Abu Hanifa al-Nu''man ibn Thabit (c. 699-767 CE) of Kufa, eponymous founder of the Hanafi school, the most widely followed Sunni legal tradition.','scholarly attestation'),
 ('ENT_ISL_MALIK_IBN_ANAS','SRC_ISLAMIC_TRADITION','Malik ibn Anas (c. 711-795 CE) of Medina founded the Maliki school and authored the Muwatta, an early collection of hadith and law.','scholarly attestation'),
 ('ENT_ISL_AL_SHAFII','SRC_ISLAMIC_TRADITION','Muhammad ibn Idris al-Shafi''i (767-820 CE) founded the Shafi''i school and is regarded as the father of Islamic legal theory in his Risala.','scholarly attestation'),
 ('ENT_ISL_AHMAD_IBN_HANBAL','SRC_ISLAMIC_TRADITION','Ahmad ibn Hanbal (780-855 CE) of Baghdad founded the Hanbali school, emphasized hadith over speculative reasoning, and compiled the vast Musnad.','scholarly attestation'),
 ('ENT_ISL_TALHA','SRC_SAHIH_BUKHARI','One of the Ten Promised Paradise who famously shielded Muhammad at Uhud, sustaining wounds to his hand.','scholarly attestation'),
 ('ENT_ISL_AL_ZUBAYR','SRC_SAHIH_BUKHARI','A paternal cousin of the Prophet and husband of Asma bint Abi Bakr, among the Ten Promised Paradise.','scholarly attestation'),
 ('ENT_ISL_ABD_AL_RAHMAN_IBN_AWF','SRC_SAHIH_BUKHARI','A prosperous early Muslim merchant, one of the Ten Promised Paradise, and a member of Umar''s electoral council (shura).','scholarly attestation'),
 ('ENT_ISL_SAD_IBN_ABI_WAQQAS','SRC_SAHIH_BUKHARI','One of the Ten Promised Paradise who commanded the army that defeated the Sasanian Persians at al-Qadisiyya.','scholarly attestation'),
 ('ENT_ISL_SAID_IBN_ZAYD','SRC_SAHIH_BUKHARI','One of the Ten Promised Paradise, an early convert whose conversion (with his wife Fatima) preceded Umar''s own.','scholarly attestation'),
 ('ENT_ISL_ABU_UBAYDA','SRC_SAHIH_BUKHARI','One of the Ten Promised Paradise who commanded the conquest of Syria and was titled Amin al-Umma (Trustee of the Community).','scholarly attestation'),
 ('ENT_ISL_SAWDA','SRC_IBN_ISHAQ_SIRA','The first woman Muhammad married after Khadijah''s death, who had earlier emigrated to Abyssinia with her first husband.','scholarly attestation'),
 ('ENT_ISL_HAFSA','SRC_IBN_ISHAQ_SIRA','Daughter of the second caliph Umar, who kept the original compiled manuscript (suhuf) of the Qur''an after Abu Bakr.','scholarly attestation'),
 ('ENT_ISL_ZAYNAB_BINT_JAHSH','SRC_IBN_ISHAQ_SIRA','The Prophet''s cousin and formerly wife of his adopted son Zayd, whose marriage is addressed in Surah al-Ahzab.','scholarly attestation'),
 ('ENT_ISL_UMM_SALAMA','SRC_IBN_ISHAQ_SIRA','Hind bint Abi Umayya, a prolific narrator of hadith credited with the advice that resolved the crisis at Hudaybiyya.','scholarly attestation'),
 ('ENT_ISL_JUWAYRIYA','SRC_IBN_ISHAQ_SIRA','Daughter of the Banu Mustaliq chief; her marriage to the Prophet prompted Muslims to free their captives from her tribe.','scholarly attestation'),
 ('ENT_ISL_SAFIYYA','SRC_IBN_ISHAQ_SIRA','A noblewoman of the Jewish Banu Nadir and daughter of its chief, who became the Prophet''s wife after the Battle of Khaybar.','scholarly attestation'),
 ('ENT_ISL_UMM_HABIBA','SRC_IBN_ISHAQ_SIRA','Ramla bint Abi Sufyan, daughter of the Quraysh chief Abu Sufyan, an emigrant to Abyssinia married to the Prophet by proxy of the Negus.','scholarly attestation'),
 ('ENT_ISL_MAYMUNA','SRC_IBN_ISHAQ_SIRA','The last woman Muhammad married, wed during the fulfilled compensatory pilgrimage (umrat al-qada) of 7 AH.','scholarly attestation'),
 ('ENT_ISL_ZAYNAB_BINT_KHUZAYMA','SRC_IBN_ISHAQ_SIRA','Called Umm al-Masakin (''Mother of the Poor'') for her generosity, she died only a few months after marrying the Prophet.','scholarly attestation'),
 ('ENT_ISL_ASMA_AL_HUSNA','SRC_ISLAMIC_TRADITION','Al-Asma al-Husna are the ninety-nine Beautiful Names of God (al-Rahman, al-Rahim, al-Malik, ...) enumerated in tradition and recited in devotion; names of the one God, not separate beings.','scholarly attestation');
INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_ISR_ABIJAH','PER_ISR_IRON_AGE','Son of Rehoboam who warred against Jeroboam I and won at Mount Zemaraim, reigning three years.'),
 ('ENT_ISR_ATHALIAH','PER_ISR_IRON_AGE','Daughter of Ahab/Jezebel who seized Judah''s throne after Ahaziah''s death and slaughtered the royal heirs, ruling six years until executed by Jehoiada.'),
 ('ENT_ISR_JEHORAM_JUDAH','PER_ISR_IRON_AGE','Son of Jehoshaphat who married Athaliah, killed his brothers, lost Edom in revolt, and died of an incurable disease.'),
 ('ENT_ISR_AHAZIAH_JUDAH','PER_ISR_IRON_AGE','Son of Jehoram and Athaliah who reigned one year and was killed by Jehu during his revolt.'),
 ('ENT_ISR_JOASH_JUDAH','PER_ISR_IRON_AGE','Hidden as an infant from Athaliah and enthroned at seven by the priest Jehoiada; repaired the Temple but later apostatized and was assassinated.'),
 ('ENT_ISR_AMAZIAH','PER_ISR_IRON_AGE','Son of Joash who defeated Edom but was beaten and captured by Jehoash of Israel and later killed in a conspiracy at Lachish.'),
 ('ENT_ISR_JOTHAM','PER_ISR_IRON_AGE','Son of Uzziah who served as regent during his father''s leprosy, built the Upper Gate of the Temple, and is judged generally righteous.'),
 ('ENT_ISR_AMON_JUDAH','PER_ISR_IRON_AGE','Son of Manasseh who continued his father''s idolatry and was assassinated by his servants after two years.'),
 ('ENT_ISR_JEHOAHAZ_JUDAH','PER_ISR_IRON_AGE','Son of Josiah (Shallum) who reigned three months before Pharaoh Necho deposed him and carried him to Egypt, where he died.'),
 ('ENT_ISR_JEHOIAKIM','PER_ISR_IRON_AGE','Son of Josiah installed by Necho who became Nebuchadnezzar''s vassal, rebelled, burned Jeremiah''s scroll, and died as Babylon advanced.'),
 ('ENT_ISR_JEHOIACHIN','PER_ISR_IRON_AGE','Son of Jehoiakim who reigned three months before surrendering in the 597 BCE deportation, later released from prison by Evil-merodach.'),
 ('ENT_ISR_NADAB','PER_ISR_IRON_AGE','Son of Jeroboam I who reigned two years before Baasha assassinated him at Gibbethon and wiped out his father''s dynasty.'),
 ('ENT_ISR_BAASHA','PER_ISR_IRON_AGE','Founder of his own house who seized the throne by killing Nadab, warred against Asa, and was condemned by the prophet Jehu son of Hanani.'),
 ('ENT_ISR_ELAH','PER_ISR_IRON_AGE','Son of Baasha who reigned two years and was murdered while drunk by his chariot commander Zimri.'),
 ('ENT_ISR_ZIMRI','PER_ISR_IRON_AGE','A chariot officer who killed Elah and reigned only seven days before Omri besieged him, whereupon he burned the palace over himself.'),
 ('ENT_ISR_TIBNI','PER_ISR_IRON_AGE','Son of Ginath supported by half of Israel against Omri in a succession struggle, but his faction was defeated and he died.'),
 ('ENT_ISR_AHAZIAH_ISRAEL','PER_ISR_IRON_AGE','Son of Ahab who reigned two years, served Baal, and after falling through a lattice consulted Baal-zebub and died as Elijah foretold.'),
 ('ENT_ISR_JEHORAM_ISRAEL','PER_ISR_IRON_AGE','Son of Ahab (Joram) who fought Moab and Aram and was killed by Jehu during his coup, ending the Omride dynasty.'),
 ('ENT_ISR_JEHOAHAZ_ISRAEL','PER_ISR_IRON_AGE','Son of Jehu whose reign saw Israel ground down by Hazael of Aram until only a remnant army remained.'),
 ('ENT_ISR_JEHOASH_ISRAEL','PER_ISR_IRON_AGE','Son of Jehoahaz (Joash) who recovered cities from Aram per Elisha''s deathbed prophecy and defeated Amaziah of Judah.'),
 ('ENT_ISR_ZECHARIAH_ISRAEL','PER_ISR_IRON_AGE','Son of Jeroboam II who reigned six months before Shallum assassinated him, ending Jehu''s dynasty in the fourth generation.'),
 ('ENT_ISR_SHALLUM_ISRAEL','PER_ISR_IRON_AGE','Son of Jabesh who killed Zechariah and reigned a single month before Menahem struck him down.'),
 ('ENT_ISR_MENAHEM','PER_ISR_IRON_AGE','Son of Gadi who seized power by killing Shallum, sacked Tiphsah, and paid tribute to Pul (Tiglath-pileser III) of Assyria.'),
 ('ENT_ISR_PEKAHIAH','PER_ISR_IRON_AGE','Son of Menahem who reigned two years before his officer Pekah assassinated him in the citadel of Samaria.'),
 ('ENT_ISR_PEKAH','PER_ISR_IRON_AGE','Son of Remaliah who killed Pekahiah, allied with Rezin of Aram against Judah, lost much land to Tiglath-pileser III, and was killed by Hoshea.'),
 ('ENT_ISR_HOSHEA','PER_ISR_IRON_AGE','Final northern king who killed Pekah, became an Assyrian vassal but conspired with Egypt, and was imprisoned as Samaria fell and Israel was deported in 722 BCE.'),
 ('ENT_NT_PROCHORUS','PER_APOSTOLIC','One of the seven men of good repute appointed in Acts 6:5 to oversee the daily distribution to the Hellenist widows.'),
 ('ENT_NT_NICANOR','PER_APOSTOLIC','One of the seven deacons named in Acts 6:5, set apart by the apostles with prayer and the laying on of hands.'),
 ('ENT_NT_TIMON','PER_APOSTOLIC','One of the seven deacons listed in Acts 6:5 to relieve the apostles of the daily ministration.'),
 ('ENT_NT_PARMENAS','PER_APOSTOLIC','One of the seven deacons named in Acts 6:5 among those chosen to administer the church''s daily distribution.'),
 ('ENT_NT_NICOLAUS','PER_APOSTOLIC','The last-named of the seven deacons in Acts 6:5, identified as a proselyte from Antioch.'),
 ('ENT_NT_CORNELIUS','PER_APOSTOLIC','A God-fearing centurion at Caesarea who, after a vision, was baptized by Peter and became the first Gentile convert (Acts 10).'),
 ('ENT_NT_ANANIAS_DAMASCUS','PER_APOSTOLIC','A disciple at Damascus sent in a vision to lay hands on Saul of Tarsus, restoring his sight and baptizing him (Acts 9:10-19).'),
 ('ENT_NT_GAMALIEL','PER_APOSTOLIC','A respected Pharisee who counseled restraint toward the apostles (Acts 5:34) and at whose feet Paul was educated (Acts 22:3).'),
 ('ENT_NT_AGABUS','PER_APOSTOLIC','A Christian prophet who foretold a great famine (Acts 11:28) and predicted Paul''s arrest in Jerusalem (Acts 21:10-11).'),
 ('ENT_NT_TABITHA','PER_APOSTOLIC','A disciple of Joppa known for charity and garment-making who was raised from the dead by Peter (Acts 9:36-42).'),
 ('ENT_NT_ETHIOPIAN_EUNUCH','PER_APOSTOLIC','The treasurer of Candace, queen of the Ethiopians, who was reading Isaiah when Philip explained the Scripture and baptized him (Acts 8:26-39).'),
 ('ENT_NT_PHOEBE','PER_APOSTOLIC','A deacon (diakonos) of the church at Cenchreae whom Paul commends as a benefactor and entrusts to the Roman church (Romans 16:1-2).'),
 ('ENT_NT_JUNIA','PER_APOSTOLIC','A kinswoman and fellow prisoner of Paul, greeted in Romans 16:7 as outstanding among the apostles.'),
 ('ENT_NT_ONESIMUS','PER_APOSTOLIC','The slave of Philemon who, converted by Paul in prison, was sent back as a beloved brother (Philemon 10-16).'),
 ('ENT_NT_PHILEMON','PER_APOSTOLIC','A Christian of Colossae and host of a house church, addressed by Paul in the Epistle to Philemon on behalf of his slave Onesimus.'),
 ('ENT_NT_EPAPHRAS','PER_APOSTOLIC','A fellow servant who brought the gospel to Colossae and is named as Paul''s fellow prisoner (Colossians 1:7; 4:12).'),
 ('ENT_NT_ONESIPHORUS','PER_APOSTOLIC','A supporter who often refreshed Paul and, unashamed of his chains, diligently sought him out in Rome (2 Timothy 1:16-18).'),
 ('ENT_ISL_FOUR_IMAMS','PER_ISL_CLASSICAL','Sunni Islam recognizes four orthodox schools of law, each named for a jurist of the 8th-9th centuries CE whose legal methodology it codified.'),
 ('ENT_ISL_ABU_HANIFA','PER_ISL_CLASSICAL','Abu Hanifa al-Nu''man ibn Thabit (c. 699-767 CE) of Kufa, eponymous founder of the Hanafi school, the most widely followed Sunni legal tradition.'),
 ('ENT_ISL_MALIK_IBN_ANAS','PER_ISL_CLASSICAL','Malik ibn Anas (c. 711-795 CE) of Medina founded the Maliki school and authored the Muwatta, an early collection of hadith and law.'),
 ('ENT_ISL_AL_SHAFII','PER_ISL_CLASSICAL','Muhammad ibn Idris al-Shafi''i (767-820 CE) founded the Shafi''i school and is regarded as the father of Islamic legal theory in his Risala.'),
 ('ENT_ISL_AHMAD_IBN_HANBAL','PER_ISL_CLASSICAL','Ahmad ibn Hanbal (780-855 CE) of Baghdad founded the Hanbali school, emphasized hadith over speculative reasoning, and compiled the vast Musnad.'),
 ('ENT_ISL_TALHA','PER_ISL_EARLY','One of the Ten Promised Paradise who famously shielded Muhammad at Uhud, sustaining wounds to his hand.'),
 ('ENT_ISL_AL_ZUBAYR','PER_ISL_EARLY','A paternal cousin of the Prophet and husband of Asma bint Abi Bakr, among the Ten Promised Paradise.'),
 ('ENT_ISL_ABD_AL_RAHMAN_IBN_AWF','PER_ISL_EARLY','A prosperous early Muslim merchant, one of the Ten Promised Paradise, and a member of Umar''s electoral council (shura).'),
 ('ENT_ISL_SAD_IBN_ABI_WAQQAS','PER_ISL_EARLY','One of the Ten Promised Paradise who commanded the army that defeated the Sasanian Persians at al-Qadisiyya.'),
 ('ENT_ISL_SAID_IBN_ZAYD','PER_ISL_EARLY','One of the Ten Promised Paradise, an early convert whose conversion (with his wife Fatima) preceded Umar''s own.'),
 ('ENT_ISL_ABU_UBAYDA','PER_ISL_EARLY','One of the Ten Promised Paradise who commanded the conquest of Syria and was titled Amin al-Umma (Trustee of the Community).'),
 ('ENT_ISL_SAWDA','PER_ISL_EARLY','The first woman Muhammad married after Khadijah''s death, who had earlier emigrated to Abyssinia with her first husband.'),
 ('ENT_ISL_HAFSA','PER_ISL_EARLY','Daughter of the second caliph Umar, who kept the original compiled manuscript (suhuf) of the Qur''an after Abu Bakr.'),
 ('ENT_ISL_ZAYNAB_BINT_JAHSH','PER_ISL_EARLY','The Prophet''s cousin and formerly wife of his adopted son Zayd, whose marriage is addressed in Surah al-Ahzab.'),
 ('ENT_ISL_UMM_SALAMA','PER_ISL_EARLY','Hind bint Abi Umayya, a prolific narrator of hadith credited with the advice that resolved the crisis at Hudaybiyya.'),
 ('ENT_ISL_JUWAYRIYA','PER_ISL_EARLY','Daughter of the Banu Mustaliq chief; her marriage to the Prophet prompted Muslims to free their captives from her tribe.'),
 ('ENT_ISL_SAFIYYA','PER_ISL_EARLY','A noblewoman of the Jewish Banu Nadir and daughter of its chief, who became the Prophet''s wife after the Battle of Khaybar.'),
 ('ENT_ISL_UMM_HABIBA','PER_ISL_EARLY','Ramla bint Abi Sufyan, daughter of the Quraysh chief Abu Sufyan, an emigrant to Abyssinia married to the Prophet by proxy of the Negus.'),
 ('ENT_ISL_MAYMUNA','PER_ISL_EARLY','The last woman Muhammad married, wed during the fulfilled compensatory pilgrimage (umrat al-qada) of 7 AH.'),
 ('ENT_ISL_ZAYNAB_BINT_KHUZAYMA','PER_ISL_EARLY','Called Umm al-Masakin (''Mother of the Poor'') for her generosity, she died only a few months after marrying the Prophet.'),
 ('ENT_ISL_ASMA_AL_HUSNA','PER_ISL_EARLY','Al-Asma al-Husna are the ninety-nine Beautiful Names of God (al-Rahman, al-Rahim, al-Malik, ...) enumerated in tradition and recited in devotion; names of the one God, not separate beings.');
